Rules.InvariantScript:
IfError(ClearCollect(colNotas, Filter(tblNotas, Lower(Correo) = Lower(User().Email))); ClearCollect(colAuto, Filter(tblAuto, Lower(Correo) = Lower(User().Email))); true, Notify("No se pudo leer BUAI_Perfil_Datos.xlsx (tblNotas / tblAuto). Agréguelo en Datos.", NotificationType.Error); false);
If(!varCalLeido, Set(varCalLeido, true);
IfError(ClearCollect(colAgendaDia, Office365Outlook.GetEventsCalendarViewV3("Calendar", Text(DateAdd(Date(Year(varMesCal), Month(varMesCal), 1), -(Weekday(Date(Year(varMesCal), Month(varMesCal), 1), StartOfWeek.Monday) - 1), TimeUnit.Days), "yyyy-mm-dd") & "T00:00:00", Text(DateAdd(DateAdd(Date(Year(varMesCal), Month(varMesCal), 1), -(Weekday(Date(Year(varMesCal), Month(varMesCal), 1), StartOfWeek.Monday) - 1), TimeUnit.Days), 42, TimeUnit.Days), "yyyy-mm-dd") & "T00:00:00").value), Notify("No se pudo leer tu calendario de Outlook: " & FirstError.Message, NotificationType.Error); Clear(colAgendaDia)));
IfError(ClearCollect(colGestionesP, Filter(tblGestiones, Id <> "0")), Clear(colGestionesP));
If(IsBlank(varMisPrest),
    Set(varMisPrestTxt, IfError(Text('FolioUsuario'.Run(User().Email).datos), ""));
    Set(varMisPrest, ParseJSON(If(IsBlank(varMisPrestTxt), "{}", varMisPrestTxt))));
ClearCollect(colSug,
    {p: 3, ico: "moroso", t: If(!IsBlank(Text(varResumen.fecha)), Text(Value(varResumen.mor30)), "—") & " usuarios con más de 30 días de atraso; " & CountRows(Filter(colGestionesP, IfError(DateValue(Left(FechaHora, 10)), Date(1900, 1, 1)) >= Today() - 7)) & " gestiones esta semana.", a: "Ver morosos", n: 3, area: "BIBLIOTECA"},
    {p: 3, ico: "ingreso", t: Text(CountRows(Filter(colIngresos, Etapa = "En PPTT" && IsBlank('Estado PPTT')))) & " títulos en PPTT sin estado.", a: "Ver bandeja", n: 1, area: "PPTT"},
    {p: 2, ico: "ingreso", t: Text(CountRows(Filter(colIngresos, Etapa = "Registrado en Biblioteca"))) & " títulos esperan al Área de Adquisición.", a: "Ver bandeja", n: 2, area: "ADQ"},
    {p: 1, ico: "descarte", t: Text(CountRows(Filter(colFicha, IsBlank('Decisión Final Descarte SI/NO')))) & " títulos de la ficha sin decisión final.", a: "Abrir descarte", n: 4, area: "BIBLIOTECA"}
);
RemoveIf(colSug, StartsWith(t, "0 ") || StartsWith(t, "— "))
